    roots = [Path(p).expanduser().resolve() for p in os.environ.get("ENGCIM_ALLOWED_ROOTS","").split(":") if p]
    if not roots:
        print("DENY no ENGCIM_ALLOWED_ROOTS configured"); return 1
    target = Path(sys.argv[1]).expanduser().resolve()
    for root in roots:
